<template><div class="sf-slider"><div><label :for="id">{{ label }}</label><output :for="id">{{ value }}{{ unit }}</output></div><input :id="id" type="range" :min="min" :max="max" :step="step" :value="value" :disabled="disabled" :aria-valuetext="value+unit" @input="$emit('input',Number($event.target.value))"/><p v-if="help">{{ help }}</p></div></template>
<script>let sequence=0;export default {name:'SfSlider',props:{value:{type:Number,required:true},label:{type:String,required:true},min:{type:Number,default:0},max:{type:Number,default:100},step:{type:Number,default:1},unit:{type:String,default:''},help:String,disabled:Boolean},data(){return {id:'sf-slider-'+(++sequence)}}}</script>
